WITH base AS (
  SELECT "NCT", "Author" AS "Author", "Year", "PubMed ID" AS "PMID", "Cancer type", "Trial name", "Is any other biomarker used for inclusion"
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%breast%' AND "Is any other biomarker used for inclusion" = 'Yes'
)
SELECT * FROM base;
